<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useMutation, useQuery, useQueryClient } from '@tanstack/vue-query'
import type { components } from '../api/generated/voltbridge-schema'
import { api, unwrap } from '../api/client'
import { ElMessage } from 'element-plus'
import { isTariffFormValid } from '../api/tariff-form'
type Create=components['schemas']['CreateTariffRequest'];type Tariff=components['schemas']['TariffPlanView']
const qc=useQueryClient(),tenant=ref(localStorage.getItem('voltbridge.tenantId')||import.meta.env.VITE_DEFAULT_TENANT_ID||''),dialog=ref(false),selected=ref<Tariff|null>(null)
const form=reactive<Create>({tenantId:'',name:'',currency:'CNY',energyPricePerKwh:0,serviceFeePerKwh:0,effectiveFrom:new Date().toISOString(),effectiveTo:undefined})
const plans=useQuery({queryKey:['tariffs',tenant],enabled:computed(()=>!!tenant.value),queryFn:async()=>{localStorage.setItem('voltbridge.tenantId',tenant.value);return unwrap<Tariff[]>(await api.GET('/api/tariffs',{params:{query:{tenantId:tenant.value}}}))}})
const create=useMutation({mutationFn:async()=>unwrap<Tariff>(await api.POST('/api/tariffs',{body:form})),onSuccess:async()=>{dialog.value=false;ElMessage.success('Tariff created');await qc.invalidateQueries({queryKey:['tariffs',tenant.value]})}})
const activate=useMutation({mutationFn:async(id:string)=>unwrap<Tariff>(await api.POST('/api/tariffs/{tariffPlanId}/activate',{params:{path:{tariffPlanId:id}}})),onSuccess:async data=>{selected.value=data;await Promise.all([qc.invalidateQueries({queryKey:['tariffs',tenant.value]}),qc.invalidateQueries({queryKey:['tariff',data.id]})])}})
function openCreate(){Object.assign(form,{tenantId:tenant.value,name:'',currency:'CNY',energyPricePerKwh:0,serviceFeePerKwh:0,effectiveFrom:new Date().toISOString(),effectiveTo:undefined});create.reset();dialog.value=true}
function submit(){if(!isTariffFormValid(form,tenant.value))return;form.tenantId=tenant.value;create.mutate()}
</script>
<template><div class="page"><div class="page-title"><div><span class="eyebrow">PRICING</span><h1>Tariffs</h1></div><el-button type="primary" @click="openCreate">Create tariff</el-button></div>
<el-card><template #header><div class="section-head"><span>Tenant tariffs</span><span class="muted">Operator context value</span></div></template><el-form inline @submit.prevent><el-form-item label="Tenant ID"><el-input v-model="tenant" placeholder="Tenant UUID" @change="plans.refetch()"/></el-form-item></el-form><el-alert v-if="plans.isError.value" type="error" :title="plans.error.value?.message||'Could not load tariffs'" :closable="false"/><el-skeleton v-else-if="plans.isLoading.value" :rows="4" animated/><el-empty v-else-if="!plans.data.value?.length" description="No tariffs returned for this tenant"/><el-table v-else :data="plans.data.value"><el-table-column prop="name" label="Name"/><el-table-column prop="pricingType" label="Pricing"/><el-table-column prop="energyPricePerKwh" label="Energy / kWh"/><el-table-column prop="serviceFeePerKwh" label="Service / kWh"/><el-table-column prop="currency" label="Currency"/><el-table-column prop="status" label="Status"/><el-table-column label="Actions"><template #default="scope"><el-button v-if="scope.row.status!=='ACTIVE'" link type="primary" :loading="activate.isPending.value" @click="activate.mutate(scope.row.id)">Activate</el-button><el-button link @click="selected=scope.row">Inspect</el-button></template></el-table-column></el-table><el-alert v-if="activate.isError.value" class="mt" type="error" :title="activate.error.value?.message||'Activation rejected'" :closable="false"/></el-card>
<el-dialog v-model="dialog" title="Create fixed-rate tariff" width="560px"><el-alert v-if="create.isError.value" type="error" :title="create.error.value?.message||'Create request rejected'" :closable="false"/><el-form label-position="top"><el-form-item label="Tenant ID" required><el-input v-model="form.tenantId" disabled/></el-form-item><el-form-item label="Name" required><el-input v-model="form.name" maxlength="128"/></el-form-item><el-form-item label="Currency" required><el-input v-model="form.currency"/></el-form-item><el-form-item label="Energy price per kWh" required><el-input-number v-model="form.energyPricePerKwh" :min="0" :precision="2"/></el-form-item><el-form-item label="Service fee per kWh" required><el-input-number v-model="form.serviceFeePerKwh" :min="0" :precision="2"/></el-form-item><el-form-item label="Effective from" required><el-date-picker v-model="form.effectiveFrom" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss[Z]"/></el-form-item><el-form-item label="Effective to"><el-date-picker v-model="form.effectiveTo" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss[Z]"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">Cancel</el-button><el-button type="primary" :loading="create.isPending.value" @click="submit">Create tariff</el-button></template></el-dialog>
<el-drawer v-model="selected" title="Tariff details" size="420px"><pre v-if="selected">{{JSON.stringify(selected,null,2)}}</pre></el-drawer></div></template>
